// migration-plan.mjs — the PURE half of the committed-migration gate
// (generated by Nous, IMP-363). Node builtins only: NO `pg`, NO `dotenv`, no
// third-party import. That is deliberate — it lets this file be executed and
// asserted on directly, with no `pnpm install` and no database, by both the
// substrate's test suite and anyone debugging a migration history by hand.
//
// The I/O shell lives in `apply-migrations.mjs` and imports this. Keep the
// split: every fault this gate catches is a decision over two lists.
import { createHash } from "node:crypto";

/** Content hash of one migration's SQL. The ledger stores this, so an edit to an
 *  already-applied migration is detectable rather than silent. */
export function digest(sql) {
  return createHash("sha256").update(sql).digest("hex");
}

/** Raised for an ILLEGAL history — never for ordinary pending work. */
export class MigrationPlanError extends Error {
  constructor(message) {
    super(message);
    this.name = "MigrationPlanError";
  }
}

/**
 * Decide what to apply.
 *
 * @param committed [{ filename, sha256 }] — every committed migration, sorted by
 *   filename (HR-25 timestamp-slug names sort chronologically).
 * @param applied   [{ filename, sha256 }] — the ledger rows, in applied order.
 * @returns { pending, total } — `pending` is the tail still to run.
 *
 * Throws MigrationPlanError when the applied history is not an exact PREFIX of
 * the committed list (a migration was deleted, renamed, reordered, or inserted
 * behind one already applied), or when an applied migration's committed bytes
 * have CHANGED since it ran. Both are unrecoverable by re-running: the database
 * no longer matches what the repository says was applied to it.
 */
export function planMigrations(committed, applied) {
  for (const [index, appliedMigration] of applied.entries()) {
    const committedMigration = committed[index];
    if (
      !committedMigration ||
      committedMigration.filename !== appliedMigration.filename
    ) {
      throw new MigrationPlanError(
        "applied migration history is not an exact prefix of committed migrations: " +
          `position ${index + 1} recorded ${appliedMigration.filename}, ` +
          `committed ${committedMigration?.filename ?? "<missing>"}`,
      );
    }
    if (appliedMigration.sha256 !== committedMigration.sha256) {
      throw new MigrationPlanError(
        `checksum mismatch for applied migration ${committedMigration.filename}: ` +
          `recorded ${appliedMigration.sha256}, committed ${committedMigration.sha256}`,
      );
    }
  }
  return { pending: committed.slice(applied.length), total: committed.length };
}
